(() => {
  'use strict';
  const {products, storageKey, coupon} = window.SHOP;
  const $ = s => document.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const product = id => products.find(p => p.id === id);
  const money = n => (n / 100).toFixed(n % 100 ? 2 : 0);
  const label = type => ({case:'成品资料',course:'精品课程',idea:'思路库',member:'研习会员'}[type] || '全部内容');
  const date = ts => new Date(ts).toLocaleString('zh-CN',{hour12:false});
  const main = $('#main');
  $('.skip').addEventListener('click', e => { e.preventDefault(); main.focus({preventScroll:true}); main.scrollIntoView({block:'start'}); });
  let saved = {};
  try { saved = JSON.parse(localStorage.getItem(storageKey) || '{}') || {}; } catch { saved = {}; }
  const state = {
    cart:Array.isArray(saved.cart) ? [...new Set(saved.cart.filter(id=>product(id)))] : [],
    favorites:Array.isArray(saved.favorites) ? [...new Set(saved.favorites.filter(id=>product(id)))] : [],
    profile:typeof saved.profile === 'string' ? saved.profile.slice(0,24) : '',
    orders:Array.isArray(saved.orders) ? saved.orders.filter(o=>o && /^DEMO-[A-Z0-9-]+$/.test(o.id) && ['pending','delivered'].includes(o.status) && Number.isFinite(o.created) && Array.isArray(o.items) && o.items.length && o.items.every(id=>product(id)) && Number.isInteger(o.total) && o.total>=0).slice(0,100) : [],
    progress:saved.progress && typeof saved.progress === 'object' ? saved.progress : {},
    coupons:Array.isArray(saved.coupons)?saved.coupons.filter(c=>c&&typeof c.code==='string'&&/^[A-Z0-9-]{3,24}$/.test(c.code)&&['percent','fixed'].includes(c.kind)&&Number.isFinite(c.value)&&c.value>0&&Number.isFinite(c.minimum)&&c.minimum>=0):[{code:'DEMO20',kind:'percent',value:20,minimum:0,start:'',end:'',active:true}],
    deliveries:saved.deliveries&&typeof saved.deliveries==='object'&&!Array.isArray(saved.deliveries)?saved.deliveries:{},
    coupon:null,homeType:'all',detailTab:'intro',editingCoupon:null,deliveryProduct:'optimization'
  };
  let toastTimer, modalOpener, storageWarned = false;
  function persist(){try{localStorage.setItem(storageKey,JSON.stringify({cart:state.cart,favorites:state.favorites,profile:state.profile,orders:state.orders,progress:state.progress,coupons:state.coupons,deliveries:state.deliveries}));}catch{if(!storageWarned){storageWarned=true;toast('浏览器未允许保存，体验数据仅保留到本次页面关闭。');}}updateBadge();}
  function updateBadge(){ $('#cart-count').textContent=state.cart.length; $('.account-btn').textContent='订单取货'; $('.cart-link').setAttribute('aria-label',`购物车，共 ${state.cart.length} 件商品`); }
  function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
  function modal(title,body){modalOpener=document.activeElement;$('#modal').innerHTML=`<button class="modal-close" data-action="close-modal" aria-label="关闭对话框">×</button><h2 id="modal-title">${esc(title)}</h2>${body}`;$('#modal').showModal();}
  function closeModal(){ $('#modal').close(); if(modalOpener?.isConnected) modalOpener.focus(); }
  $('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
  function go(path){if(location.hash===`#${path}`)render();else location.hash=path;}
  function price(p){return `<span class="price"><small>¥</small>${money(p.price)}<span class="price-note">示例价</span></span>`;}
  function chart(kind,hero=false){
    let body='';
    const axes='<path d="M38 22V167H335" fill="none" stroke="currentColor" opacity=".22"/><path d="M38 58H335M38 94H335M38 130H335M98 22V167M158 22V167M218 22V167M278 22V167" fill="none" stroke="currentColor" opacity=".07"/>';
    if(kind==='pareto'){
      const pts=[[60,55],[86,77],[114,99],[144,118],[185,133],[234,143],[301,151]];
      body=axes+'<path d="M60 55C98 91 135 132 301 151" fill="none" stroke="currentColor" stroke-width="2.5"/>'+pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="currentColor" stroke-width="2"/>`).join('')+[[67,24],[105,44],[128,64],[157,48],[164,97],[196,91],[219,120],[275,99],[291,125],[243,65]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.3" fill="currentColor" opacity=".19"/>`).join('');
      if(hero)body+='<text x="215" y="192" fill="#7b8fa9" font-size="11">目标一：成本</text><text x="0" y="14" fill="#7b8fa9" font-size="11">目标二：时间</text><path d="M164 108L187 80" stroke="#7695bf" stroke-dasharray="3 3"/><rect x="184" y="56" width="95" height="25" rx="4" fill="#ecf3fd"/><text x="196" y="73" fill="#426ca2" font-size="11">更优的权衡方案</text>';
    } else if(kind==='line')body=axes+'<path d="M38 145L68 135L93 142L118 100L143 113L169 85L193 95L218 57L248 72L278 36L313 48" fill="none" stroke="currentColor" stroke-width="2.8"/><path d="M38 130L68 131L93 122L118 116L143 104L169 96L193 85L218 80L248 59L278 56L313 35" fill="none" stroke="currentColor" opacity=".3" stroke-width="2" stroke-dasharray="5 5"/>';
    else if(kind==='scatter')body=axes+Array.from({length:23},(_,i)=>{const x=50+i*12;const y=153-i*5+Math.sin(i*3)*24;return `<circle cx="${x}" cy="${y}" r="${i%4===0?5:3}" fill="currentColor" opacity="${.3+i%3*.2}"/>`;}).join('')+'<path d="M45 159L320 39" stroke="currentColor" stroke-width="2" stroke-dasharray="4 4"/>';
    else if(kind==='bars')body=axes+[51,79,108,91,135,119].map((h,i)=>`<rect x="${67+i*43}" y="${167-h}" width="23" height="${h}" rx="3" fill="currentColor" opacity="${.3+i*.1}"/>`).join('');
    else if(kind==='radar')body='<g transform="translate(197 101)"><path d="M0-77L73-24L45 62L-45 62L-73-24Z M0-48L46-15L28 39L-28 39L-46-15Z M0-22L21-7L13 18L-13 18L-21-7Z M0-77V0M73-24L0 0M45 62L0 0M-45 62L0 0M-73-24L0 0" stroke="currentColor" fill="none" opacity=".18"/><path d="M0-66L57-19L28 38L-41 55L-49-16Z" stroke="currentColor" stroke-width="2" fill="currentColor" fill-opacity=".12"/><path d="M0-39L67-22L39 53L-23 32L-65-21Z" stroke="currentColor" stroke-width="1.4" fill="none" stroke-dasharray="4 4" opacity=".5"/></g>';
    else body='<path d="M66 107L126 43L197 88L261 34L308 116L221 159L197 88L126 43L138 156L66 107L197 88L308 116M138 156L221 159" stroke="currentColor" stroke-opacity=".27" stroke-width="1.5" fill="none"/><path d="M66 107L197 88L261 34L308 116" stroke="currentColor" stroke-width="2.5" fill="none"/>'+[[66,107],[126,43],[197,88],[261,34],[308,116],[221,159],[138,156]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i===2?10:6}" fill="white" stroke="currentColor" stroke-width="2"/>`).join('');
    return `<svg class="chart" viewBox="0 0 360 200" ${hero?'role="img" aria-label="多目标优化示意图，沿 Pareto 前沿寻找成本与时间的权衡"':'aria-hidden="true"'}>${body}</svg>`;
  }
  function cover(p,linked=true){const inner=`<div class="cover-top"><span>DAIMENGGUI / ${p.type==='case'?'CASE STUDY':p.type==='course'?'MASTER CLASS':'MODELING NOTES'}</span><span class="cover-badge">示例内容</span></div><div class="cover-title">${esc(p.subtitle.split('，')[0].split('·')[0])}</div><div class="cover-formula">${{pareto:'min f(x)',scatter:'y = f(x)',radar:'wᵀ · x',line:'ŷ(t + 1)',network:'G = (V, E)',bars:'Σ xᵢ / n'}[p.graph]}</div>${chart(p.graph)}<span class="cover-watermark">待梦归数模 · ${esc(p.event)} / ${esc(p.version)}</span>`;return linked?`<a class="cover ${p.color}" href="#/product/${p.id}" tabindex="-1" aria-hidden="true">${inner}</a>`:`<div class="cover ${p.color}">${inner}</div>`;}
  function card(p){return `<article class="product-card">${cover(p)}<div class="card-content"><div class="card-labels"><span>${label(p.type)}</span><span>${esc(p.event)}</span><span class="version">v${p.version}</span></div><h3><a href="#/product/${p.id}">${esc(p.title)}</a></h3><p class="card-desc">${esc(p.format)}</p><div class="card-bottom">${price(p)}<button class="add-cart" data-action="add-cart" data-id="${p.id}">${state.cart.includes(p.id)?'已加入购物车':'加入购物车'}</button></div></div></article>`;}
  const faqs=[['购买后如何获取资料？','正式版计划在支付平台确认收款后发放资料或课程权限。当前演示版可通过模拟支付体验交付，并下载示例笔记；不会提供真实付费资料。'],['这里的内容与价格是真实的吗？','目前所有商品、价格和章节均为演示数据，没有展示虚构销量、获奖信息或买家评价。正式上架前会逐一补充真实资料、内容授权和交付清单。'],['资料可以直接用于参赛提交吗？','本站面向学习和研究。请结合题目独立完成建模，遵守所参加赛事的规则，并按要求注明引用来源，不应将示例资料直接作为原创成果提交。'],['资料更新和退款如何处理？','演示订单不涉及实际费用，也不发生真实退款。正式运营时，每个商品会在购买页说明版本更新范围、售后联系方式和具体退款条件。']];
  function home(){return `<section class="hero"><div class="container hero-inner"><div><div class="eyebrow">MODELING BEGINS WITH A GOOD QUESTION</div><h1>把复杂的问题，<br>变成<em>清晰的思路。</em></h1><p>精选数学建模案例、系统课程与解题思路。<br>从读懂一道题，到构建自己的完整模型。</p><div class="hero-buttons"><a class="btn orange" href="#/catalog">探索建模资料</a><a class="btn secondary" href="#/product/evaluation">免费试读</a></div><div class="hero-meta"><span>案例与代码配套</span><span>内容大纲先看</span><span>适用多类赛事</span></div></div><div class="hero-chart"><div class="chart-top"><b>一次选择，多种最优可能</b><span>MODEL / 01</span></div>${chart('pareto',true)}<div class="chart-caption"><strong>多目标优化 · Pareto 前沿</strong><span class="chart-legend">方法示意</span></div></div></div></section><div class="container category-grid"><a class="category" href="#/catalog?type=case"><span class="category-icon">∑</span><div><h3>成品资料</h3><p>完整案例 · 代码与结果</p></div><small>3 份示例</small></a><a class="category" href="#/catalog?type=course"><span class="category-icon">▷</span><div><h3>精品课程</h3><p>从基础到应用，系统学习</p></div><small>2 门示例</small></a><a class="category" href="#/catalog?type=idea"><span class="category-icon">λ</span><div><h3>解题思路库</h3><p>拆解问题，找到建模起点</p></div><small>3 份示例</small></a></div><section class="container section"><div class="section-title"><div><h2>值得研习的好内容</h2><p>选一份适合自己的资料，从一个具体问题开始。</p></div><a class="text-link" href="#/catalog">查看全部内容</a></div><div class="catalog-toolbar"><div class="tabs" role="group" aria-label="首页商品分类">${['all','case','course','idea'].map(t=>`<button class="tab ${state.homeType===t?'active':''}" data-action="home-filter" data-type="${t}" aria-pressed="${state.homeType===t}">${t==='all'?'精选推荐':label(t)}</button>`).join('')}</div><span class="fineprint" style="margin:0">商品展示为演示示例</span></div><div class="product-grid" id="home-products">${products.filter(p=>p.type!=='member'&&(state.homeType==='all'||p.type===state.homeType)).slice(0,6).map(card).join('')}</div></section><section class="standards"><div class="container section standards-grid"><div class="standard"><span class="number">01</span><div><h3>先了解，再选择</h3><p>清晰的适用场景与内容大纲，让每一次选择都有依据。</p></div></div><div class="standard"><span class="number">02</span><div><h3>让思路有迹可循</h3><p>从模型假设到结果解释，重视每一步推导和实践过程。</p></div></div><div class="standard"><span class="number">03</span><div><h3>尊重每一份原创</h3><p>关注资料来源与引用规范，将学到的方法用于独立研究。</p></div></div></div></section><section class="container section faq-layout"><div><div class="eyebrow">BEFORE YOU START</div><h2>开始之前，<br>你可能想了解</h2><p>关于内容、交付和使用方式。</p><button class="text-link" data-action="support">还有疑问？联系支持</button></div><div class="faq-list">${faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>`;}
  function filtered(params){let items=products.filter(p=>p.type!=='member');const type=params.get('type'),event=params.get('event'),q=(params.get('q')||'').trim().toLowerCase();if(type&&type!=='all')items=items.filter(p=>p.type===type);if(event&&event!=='all')items=items.filter(p=>p.event===event||p.event==='通用');if(q)items=items.filter(p=>[p.title,p.subtitle,p.desc,...p.topics].join(' ').toLowerCase().includes(q));const sort=params.get('sort');if(sort==='low')items.sort((a,b)=>a.price-b.price);if(sort==='high')items.sort((a,b)=>b.price-a.price);return items;}
  function results(params){const items=filtered(params);return items.length?items.map(card).join(''):`<div class="panel empty no-results"><div class="empty-icon">∅</div><h2>暂时没有匹配的内容</h2><p>试试“Python”“评价”或切换商品分类。</p><a class="btn secondary" href="#/catalog">重置筛选</a></div>`;}
  function catalog(params){const type=params.get('type')||'all',event=params.get('event')||'all';return `<section class="container section"><div class="page-heading"><div class="eyebrow">THE MODELING COLLECTION</div><h1>${event!=='all'?esc(event)+' · 赛事专题':label(type)}</h1><p>从一个模型、一段代码、一个好问题，开启新的研习。</p></div><div class="catalog-toolbar"><div class="tabs" role="group" aria-label="商品类型">${['all','case','course','idea'].map(t=>`<button class="tab ${type===t?'active':''}" data-action="catalog-filter" data-type="${t}" aria-pressed="${type===t}">${t==='all'?'全部':label(t)}</button>`).join('')}</div><div class="search-wrap"><input id="search" type="search" aria-label="搜索商品" placeholder="搜索模型、课程或关键词" value="${esc(params.get('q')||'')}"><select id="event-filter" aria-label="筛选赛事">${[['all','全部赛事'],['国赛','国赛'],['美赛','美赛'],['华为杯','华为杯']].map(([v,l])=>`<option value="${v}" ${v===event?'selected':''}>${l}</option>`).join('')}</select><select id="sort" aria-label="商品排序"><option value="default">推荐排序</option><option value="low" ${params.get('sort')==='low'?'selected':''}>价格从低到高</option><option value="high" ${params.get('sort')==='high'?'selected':''}>价格从高到低</option></select></div></div><p class="fineprint" id="result-count" style="margin:0 0 18px">共 ${filtered(params).length} 项内容 · 均为示例商品</p><div id="product-results" class="product-grid">${results(params)}</div></section>`;}
  function previewText(p){if(p.id==='evaluation')return '<h3>01 明确评价对象与指标</h3><p>评价模型的第一步不是选择算法，而是回答：评价什么、依据什么、数据是否可比。先列出备选对象，再把抽象目标拆解成可观测指标。</p><p>例如选择配送方案时，可考虑成本、准时率与覆盖范围。成本属于越小越好的指标，准时率通常越大越好，因此计算综合得分前需要统一指标方向并处理量纲。</p><p><b>思考练习：</b>如果成本与准时率高度相关，简单叠加两个指标会带来什么影响？尝试先检查相关性，再决定是否保留两个维度。</p>';return `<h3>${esc(p.outline[0])}</h3><p>${esc(p.desc)}</p><p>开始建模前，先界定研究对象、可获得的数据和需要解释的结果。用一份变量表记录每个量的含义、单位及范围，再区分已知参数和决策变量。</p><p><b>练习：</b>选择一个小型示例，为它写下研究问题、三个可验证的假设，以及你准备用来检验结果的方法。</p>`;}
  function detailContent(p,tab){if(tab==='outline')return `<h3>${p.type==='course'?'课程章节':'内容大纲'}</h3><ol class="outline-list">${p.outline.map((s,i)=>`<li><span>${p.type==='course'?'':String(i+1).padStart(2,'0')+'　'}${esc(s)}</span>${p.type==='course'&&i===0?`<button class="btn secondary small" data-action="preview" data-id="${p.id}">文字试看</button>`:''}</li>`).join('')}</ol>${p.type==='course'?'<p class="fineprint">当前提供文字试看；真实视频和练习包待正式上架。</p>':''}`;
    if(tab==='notice')return '<h3>购买须知</h3><p>当前站点仅用于体验，不会收取费用。示例商品的标价、目录和权益用于展示售卖流程。</p><ul><li>演示支付后只开放示例笔记和学习页面。</li><li>演示订单仅保存在当前浏览器，不会同步至其他设备。</li><li>正式销售时将单独说明版权授权、交付文件、有效期、更新和退款条件。</li><li>使用资料时请遵守赛事规则、引用要求与内容版权。</li></ul>';
    if(tab==='reviews')return '<div class="empty"><div class="empty-icon">“ ”</div><h3>还没有真实买家评价</h3><p>正式上架后，这里将展示经过核验的购买反馈。</p></div>';
    return `<h3>从理解问题开始</h3><p>${esc(p.desc)}</p><h3>适合谁研习</h3><p>${p.level==='零基础'?'希望从基础概念和动手练习开始的学习者。':p.level==='进阶'?'已有基础编程或建模经验，希望深入理解方法应用与结果分析的学习者。':'希望掌握基本方法、梳理建模步骤并建立实践习惯的学习者。'}</p><h3>${p.type==='course'?'配套学习内容':'交付内容示例'}</h3><ul>${p.files.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>${p.type==='idea'?`<h3>免费试读 · 开篇 20% 示例</h3><div class="reading">${previewText(p)}</div><p class="fineprint">此处为样章，用于演示试读体验；完整付费资料尚未上传。</p>`:''}`;
  }
  function detail(p){if(!p)return notFound();return `<section class="container section"><div class="breadcrumbs"><a href="#/">首页</a> / <a href="#/catalog?type=${p.type}">${label(p.type)}</a> / ${esc(p.title)}</div><div class="product-detail"><div>${cover(p,false)}<p class="fineprint">示例封面与方法图示 · 正式内容上架前将补充真实预览</p></div><div class="product-info"><div class="pills"><span class="pill">${label(p.type)}</span><span class="pill">${p.event}</span><span class="pill">${p.level}</span></div><h1>${esc(p.title)}</h1><p>${esc(p.subtitle)}</p><div class="pills">${p.topics.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</div><div class="purchase-box">${price(p)}<span class="muted">版本 ${p.version}<br>演示商品 · 无实际扣款</span></div><div class="actions"><button class="btn orange" data-action="buy" data-id="${p.id}">立即体验购买</button><button class="btn secondary" data-action="add-cart" data-id="${p.id}">${state.cart.includes(p.id)?'查看购物车':'加入购物车'}</button><button class="btn secondary ${state.favorites.includes(p.id)?'favorite-on':''}" data-action="favorite" data-id="${p.id}" aria-pressed="${state.favorites.includes(p.id)}">${state.favorites.includes(p.id)?'已收藏':'收藏'}</button></div><p class="fineprint">购买前可查看大纲与交付清单。课程提供文字试看，思路资料提供示例试读。</p></div></div><div class="tabs detail-tabs" role="tablist" aria-label="商品详情">${[['intro','详情介绍'],['outline','内容大纲'],['notice','购买须知'],['reviews','用户评价']].map(([t,l])=>`<button role="tab" id="tab-${t}" aria-selected="${state.detailTab===t}" aria-controls="detail-body" class="tab ${state.detailTab===t?'active':''}" data-action="detail-tab" data-tab="${t}" data-id="${p.id}">${l}</button>`).join('')}</div><div class="detail-body" id="detail-body" role="tabpanel" aria-labelledby="tab-${state.detailTab}">${detailContent(p,state.detailTab)}</div></section>`;}
  function empty(title,desc,button='浏览商品',href='/catalog'){return `<div class="panel empty"><div class="empty-icon">∅</div><h2>${title}</h2><p>${desc}</p><a class="btn" href="#${href}">${button}</a></div>`;}
  function cartRows(ids,remove){return ids.map(id=>{const p=product(id);return `<div class="cart-item">${cover(p,false)}<div><h3><a href="#/product/${id}">${esc(p.title)}</a></h3><p>${label(p.type)} · v${p.version} · 数量 1</p></div><div class="cart-item-right">${price(p)}${remove?`<button data-action="remove-cart" data-id="${id}">移除</button>`:''}</div></div>`;}).join('');}
  function validateCoupon(code,subtotal){
    const c=state.coupons.find(c=>c.code===String(code||'').trim().toUpperCase());
    if(!c)return {error:'未找到此优惠码，请检查拼写。'};
    if(!c.active)return {error:'此优惠券已停用。'};
    const now=Date.now();
    if(c.start&&now<new Date(c.start+'T00:00:00').getTime())return {error:'此优惠券尚未到使用时间。'};
    if(c.end){const end=new Date(c.end+'T00:00:00');end.setDate(end.getDate()+1);if(now>=end.getTime())return {error:'此优惠券已过期。'};}
    if(subtotal<c.minimum)return {error:`订单满 ¥${money(c.minimum)} 才能使用此优惠券。`};
    return {coupon:c,discount:Math.min(subtotal,c.kind==='fixed'?Math.round(c.value):Math.round(subtotal*c.value/100))};
  }
  function totals(ids){const subtotal=ids.reduce((s,id)=>s+product(id).price,0);const result=state.coupon?validateCoupon(state.coupon,subtotal):{};const discount=result.discount||0;return {subtotal,discount,total:subtotal-discount};}
  function totalsHTML(ids){const t=totals(ids);return `<div class="summary-line"><span>商品金额（${ids.length} 项）</span><span>¥${money(t.subtotal)}</span></div><div class="summary-line"><span>优惠${state.coupon?' · '+esc(state.coupon):''}</span><span>${t.discount?'- ¥'+money(t.discount):'—'}</span></div><div class="summary-total"><span>合计</span><span class="price"><small>¥</small>${money(t.total)}</span></div>`;}
  function cart(){return `<section class="container section"><div class="page-heading"><h1>我的购物车</h1><p>把值得研究的内容，放进你的学习计划。</p></div>${!state.cart.length?empty('购物车还是空的','去发现一份适合自己的案例、课程或思路。'):`<div class="cart-layout"><div class="panel">${cartRows(state.cart,true)}<p class="fineprint">数字商品每项限购 1 份，无需重复购买。</p></div><aside class="panel"><h3>订单摘要</h3>${totalsHTML(state.cart)}<a class="btn orange wide" href="#/checkout">前往结算</a><p class="fineprint">演示结算不会发起真实支付。</p></aside></div>`}</section>`;}
  function checkoutIds(){const id=getRoute().params.get('buy');return product(id)?[id]:state.cart;}
  function lookup(){return `<section class="container section"><div class="page-heading"><div class="eyebrow">YOUR ORDER, YOUR ACCESS</div><h1>订单取货</h1><p>无需注册或登录，使用购买凭证找到你的资料。</p></div><div class="panel article"><h2>输入订单凭证</h2><form id="lookup-form"><label class="form-label" for="order-credential">购买后生成的完整订单凭证</label><input class="field" id="order-credential" name="credential" placeholder="粘贴 DEMO- 开头的完整凭证" autocomplete="off" spellcheck="false" required maxlength="120"><p class="error" id="lookup-error" role="alert"></p><button type="submit" class="btn orange">查询订单并取货</button></form><p class="fineprint">凭证请妥善保存，不要公开分享。当前演示仅能查询此浏览器的订单；跨设备取货需要后续接入服务器。</p><div class="notice">${state.orders.length?'此浏览器保存了 '+state.orders.length+' 笔演示订单。':'还没有本机演示订单。'}</div><div class="actions"><a class="btn secondary" href="#/account/orders">查看本机订单</a><a class="text-link" href="#/catalog">继续挑选商品</a></div></div></section>`;}
  function checkout(){const ids=checkoutIds();if(!ids.length)return `<section class="container section">${empty('还没有待结算的商品','请先添加商品后再进行结算。')}</section>`;return `<section class="container section"><div class="page-heading"><div class="breadcrumbs"><a href="#/cart">购物车</a> / 确认订单</div><h1>确认你的学习清单</h1></div><form id="checkout-form"><div class="checkout-layout"><div><div class="panel"><h3>商品清单</h3>${cartRows(ids,false)}<details class="coupon"><summary>我有优惠码</summary><div class="coupon-form"><input class="field" id="coupon-input" aria-label="优惠码" placeholder="输入优惠码，如 DEMO20" value="${esc(state.coupon||'')}"><button type="button" class="btn secondary small" data-action="apply-coupon">应用</button></div><div id="coupon-message" class="coupon-message" role="status">${state.coupon?'已应用优惠码 '+esc(state.coupon):'优惠券规则由管理演示页设置'}</div></details></div><div class="panel" style="margin-top:22px"><h3>支付方式</h3><p class="fineprint">以下仅为方式选择演示，未连接任何收款账户。</p><div class="payment-options">${['微信支付','支付宝','银行卡'].map((v,i)=>`<label class="payment-option"><input type="radio" name="payment" value="${v}" ${i===0?'checked':''}> ${v}</label>`).join('')}</div><div class="notice">无需登录或填写联系方式。完成模拟购买后，请复制或保存订单凭证，以便再次取货。</div><label class="check"><input type="checkbox" id="agreement" required><span>我已阅读<a class="text-link" href="#/terms" target="_blank" rel="noopener">用户协议</a>与<a class="text-link" href="#/guide" target="_blank" rel="noopener">购买须知</a>，了解这是模拟交易。</span></label></div></div><aside class="panel checkout-summary"><h3>结算金额</h3><div id="checkout-totals">${totalsHTML(ids)}</div><button class="btn orange wide" id="checkout-submit" type="submit">创建演示订单 · ¥${money(totals(ids).total)}</button><p class="fineprint">订单只保存在此浏览器。下一步可模拟支付成功或失败，体验交付流程。</p><a class="text-link" style="display:block;margin-top:18px" href="#/cart">返回购物车</a></aside></div></form></section>`;}
  function result(id){const order=state.orders.find(o=>o.id===id);if(!order)return `<section class="container section">${empty('没有找到这笔演示订单','订单只保存在创建它的浏览器中。','查看本机订单','/account/orders')}</section>`;const done=order.status==='delivered';return `<section class="container section"><div class="panel result"><div class="result-icon ${done?'':'pending'}">${done?'✓':'¥'}</div><h1>${done?(order.total===0?'零元演示交付已完成':'模拟支付成功，示例内容已就绪'):(order.total===0?'零元演示订单已创建':'演示订单已创建')}</h1><p>${done?'未产生真实扣款。现在可以体验学习或下载示例资料。':'请选择一个支付结果，体验后续流程。'}</p><div class="notice">订单号：${order.id}<br>金额：¥${money(order.total)} · ${esc(order.payment||'模拟支付')}<br>${done?'演示交付已完成':'待模拟支付'}</div><div id="payment-error" class="error" role="status"></div><div class="actions">${done?'<a class="btn orange" href="#/account/downloads">查看示例交付</a><a class="btn secondary" href="#/account/courses">我的课程</a>':`<button class="btn orange" data-action="pay-success" data-id="${order.id}">${order.total===0?'确认零元演示交付':'模拟支付成功'}</button><button class="btn secondary" data-action="pay-fail" data-id="${order.id}">模拟支付失败</button>`}</div><p class="fineprint">${done?'请保存订单凭证。示例文件下载期限为 24 小时，可在下载页重新生成。':'此处按钮只改变本地演示状态，正式订单必须由支付平台回调确认。'}</p><div class="receipt-actions"><button class="btn secondary small" data-action="copy" data-copy="${order.id}">复制订单凭证</button><button class="btn secondary small" data-action="save-receipt" data-id="${order.id}">保存凭证文件</button></div><a class="text-link" href="#/account/orders">查看本机订单记录</a></div></section>`;}
  function purchased(type){const ids=[...new Set(state.orders.filter(o=>o.status==='delivered').flatMap(o=>o.items))];return ids.map(product).filter(p=>!type||p.type===type);}
  function hasProduct(id){return purchased().some(p=>p.id===id);}
  function latestOrder(id){return state.orders.find(o=>o.status==='delivered'&&o.items.includes(id));}
  function account(section='orders'){const sections=[['courses','我的课程'],['downloads','我的下载'],['orders','订单记录'],['favorites','我的收藏'],['coupons','优惠券'],['settings','账户设置']];if(!sections.some(([id])=>id===section))section='orders';let body='';
    if(section==='orders')body=state.orders.length?`<div class="table-wrap"><table><thead><tr><th>订单 / 商品</th><th>金额</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td><button class="text-link" data-action="copy" data-copy="${o.id}" aria-label="复制订单号 ${o.id}">${o.id}</button><br><small>${date(o.created)}</small><br>${o.items.map(id=>esc(product(id).title)).join('<br>')}</td><td>¥${money(o.total)}</td><td><span class="status ${o.status==='pending'?'pending':''}">${o.status==='delivered'?'演示已交付':'待模拟支付'}</span></td><td><a class="text-link" href="#/result/${o.id}">${o.status==='delivered'?'查看交付':'继续模拟支付'}</a></td></tr>`).join('')}</tbody></table></div>`:empty('还没有演示订单','选择一个商品，即可体验完整购买流程。');
    if(section==='downloads'){const items=purchased().filter(p=>p.type!=='course');body=items.length?`<p class="fineprint">以下为可实际下载的示例笔记，非正式商品文件。下载期限仅用于演示，不代表服务器防盗保护。</p>${items.map(p=>{const o=latestOrder(p.id),expires=Number.isFinite(o.expires)?o.expires:0;const left=Math.max(0,Math.ceil((expires-Date.now())/3600000));return `<div class="download-row"><div><h3>${esc(p.title)}</h3><p>v${p.version} · 示例 Markdown 文件 · ${left?'剩余约 '+left+' 小时':'演示期限已到'}</p><p>文件内含示例体验标识，无真实数字水印</p></div><div class="actions"><button class="btn small" data-action="download" data-id="${p.id}" ${left?'':'disabled'}>下载示例</button><button class="text-link" data-action="renew" data-id="${p.id}">重新生成期限</button></div></div>${baiduDelivery(p)}`;}).join('')}`:empty('这里将保存你的示例资料','完成一次模拟支付后，即可体验资料下载。');}
    if(section==='courses'){const items=purchased('course');body=items.length?items.map(p=>{const n=Math.min(p.outline.length,Math.max(0,Number(state.progress[p.id])||0));return `<div class="course-row"><div><h3>${esc(p.title)}</h3><p>已研习 ${n} / ${p.outline.length} 章 · 文字课程演示</p><div class="progress" role="progressbar" aria-label="${esc(p.title)}学习进度" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${p.outline.length}"><span style="width:${n/p.outline.length*100}%"></span></div></div><a class="btn small" href="#/learn/${p.id}">继续学习</a></div>`;}).join(''):empty('你的研习之旅，从这里开始','课程模拟购买完成后，可以打开文字课程并记录学习进度。','浏览课程','/catalog?type=course');}
    if(section==='favorites')body=state.favorites.length?`<div class="product-grid" style="grid-template-columns:repeat(auto-fit,minmax(215px,1fr))">${state.favorites.map(id=>card(product(id))).join('')}</div>`:empty('还没有收藏内容','在商品详情页收藏，让值得研究的内容留在身边。');
    if(section==='coupons')body=state.coupons.filter(c=>c.active).length?state.coupons.filter(c=>c.active).map(c=>`<div class="notice"><b>${esc(c.code)} · ${c.kind==='percent'?'优惠 '+c.value+'%':'减 ¥'+money(c.value)}</b><br>${c.minimum?'满 ¥'+money(c.minimum)+' 可用':'无最低消费要求'} · ${c.end?'有效至 '+esc(c.end):'未设截止日期'}<br>演示优惠券，具体可用性以结算校验为准。</div>`).join(''):'<p class="muted">目前没有启用的演示优惠券。</p>';
    if(section==='settings')body=`<p class="notice">这是保存在当前浏览器的体验身份，不是已注册账户，不提供手机或邮箱身份验证。</p><form id="profile-form"><label class="form-label" for="nickname-settings">体验昵称</label><input class="field" id="nickname-settings" name="nickname" maxlength="24" value="${esc(state.profile||'研习者')}" required><button class="btn" type="submit">保存昵称</button></form><div style="margin-top:35px"><button class="text-link" data-action="clear-data">清除本机演示数据</button><p class="fineprint">清除后将删除此站点的体验身份、购物车、收藏、订单和学习进度。</p></div>`;
    return `<section class="container section"><div class="page-heading"><h1>订单与学习空间</h1><p>收藏好内容，记录每一步学习。</p></div><div class="account-layout"><aside class="panel account-sidebar"><div class="avatar">${esc((state.profile||'研').slice(0,1))}</div><div class="user-name">${esc('访客研习者')}</div><div class="user-tag">无需登录 · 本机记录</div><nav aria-label="个人中心">${sections.map(([id,l])=>`<a class="${section===id?'active':''}" href="#/account/${id}">${l}</a>`).join('')}</nav></aside><div class="panel account-content"><h2>${sections.find(([id])=>id===section)[1]}</h2>${body}</div></div></section>`;
  }
  function learn(id){const p=product(id);if(!p||p.type!=='course')return notFound();if(!hasProduct(id))return `<section class="container section">${empty('先开启这门课程的演示权限','在商品页完成模拟购买，即可体验全部文字章节。','查看课程',`/product/${id}`)}</section>`;const progress=Math.min(p.outline.length,Math.max(0,Number(state.progress[id])||0));return `<section class="container section"><div class="breadcrumbs"><a href="#/account/courses">我的课程</a> / ${esc(p.title)}</div><article class="panel article course-reader"><div class="eyebrow">LEARNING ROOM / DEMO</div><h1>${esc(p.title)}</h1><div class="notice">文字学习体验 · 当前没有上传真实教学视频。示例章节用于检验课程、权限和进度交互。</div>${p.outline.map((s,i)=>`<details ${i===Math.min(progress,p.outline.length-1)?'open':''}><summary>${esc(s)} ${i<progress?'✓':''}</summary><p>本节学习目标：围绕“${esc(s.replace(/^\d+ /,''))}”梳理关键概念，记录输入、输出、假设与检验方法。</p><p>练习建议：选择一个小型数据集或问题，写下处理步骤，保留可复现的代码与结果，并解释方法的适用范围。正式课程上架后，此处将替换为实际视频、讲义及配套练习。</p><button class="btn secondary small" data-action="progress" data-id="${id}" data-chapter="${i+1}">${i<progress?'已记录学习':'学到这一章'}</button></details>`).join('')}<p class="fineprint">学习进度仅保存于当前浏览器。</p></article></section>`;}
  function membership(){const p=product('membership');return `<section class="container section"><div class="membership"><div><div class="eyebrow">KEEP EXPLORING</div><h1>让研习成为习惯，<br>让思路持续生长。</h1><p>把零散的学习，连接成一个持续的计划。<br>研习会员，为想多走一步的你准备。</p><p class="member-note">会员方案为演示；实际内容、咨询与更新服务尚未开通。</p></div><div class="panel"><span class="pill">月度研习计划</span><h2 style="margin-top:20px">研习会员</h2>${price(p)}<span class="muted"> / 30 天</span><ul><li>思路库阅读权益方案</li><li>资料版本更新提醒方案</li><li>每月一次课程咨询入口方案</li><li>不自动续费</li></ul><button class="btn orange wide" data-action="buy" data-id="membership">体验会员下单</button><p class="fineprint">模拟交付内容为会员权益说明，不开通真实订阅。</p></div></div></section>`;}
  function syncCoupons(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'{}');if(Array.isArray(data.coupons))state.coupons=data.coupons.filter(c=>c&&/^[A-Z0-9-]{3,24}$/.test(c.code)&&['percent','fixed'].includes(c.kind)&&Number.isFinite(c.value)&&c.value>0&&Number.isFinite(c.minimum)&&c.minimum>=0);if(data.deliveries&&typeof data.deliveries==='object'&&!Array.isArray(data.deliveries))state.deliveries=data.deliveries;}catch{}}
  function adminNav(active){return `<nav class="tabs admin-nav" aria-label="管理演示导航"><a class="tab ${active==='coupons'?'active':''}" href="#/admin/coupons">优惠券管理</a><a class="tab ${active==='delivery'?'active':''}" href="#/admin/delivery">商品交付配置</a></nav>`;}
  function validBaidu(link){try{const u=new URL(link);return u.protocol==='https:'&&u.hostname==='pan.baidu.com'&&!u.username&&!u.password&&u.pathname.startsWith('/s/')&&u.pathname.length>3;}catch{return false;}}
  function baiduDelivery(p){const c=state.deliveries[p.id];if(!c?.enabled||!validBaidu(c.link))return '';return `<div class="notice baidu-delivery"><b>百度网盘交付 · 本机演示配置</b><p>${esc(c.note||'请打开网盘链接获取资料。')}</p><div class="actions"><a class="btn small" href="${esc(c.link)}" target="_blank" rel="noopener noreferrer">打开百度网盘</a><button class="btn secondary small" data-action="copy" data-copy="${esc(c.link)}" data-copy-label="网盘链接">复制链接</button>${c.code?`<button class="btn secondary small" data-action="copy" data-copy="${esc(c.code)}" data-copy-label="提取码">复制提取码 ${esc(c.code)}</button>`:''}</div><p class="fineprint">分享链接是否有效以百度网盘实际状态为准。本站演示倒计时不改变网盘有效期。</p></div>`;}
  function adminDelivery(){const p=product(state.deliveryProduct)||product('optimization'),c=state.deliveries[p.id]||{};return `<section class="container section"><div class="page-heading"><div class="eyebrow">STORE MANAGEMENT / DEMO</div><h1>商品交付配置</h1><p>为每个资料商品设置百度网盘链接与提取码。</p></div>${adminNav('delivery')}<div class="notice">配置仅保存在本机浏览器。正式版需将这些信息保存在服务器，验证购买凭证和付款状态后再返回给客户。本页演示不提供真实管理员权限。</div><div class="panel article"><form id="delivery-admin-form"><label class="form-label" for="delivery-product">选择商品</label><select class="field" id="delivery-product" name="product">${products.filter(x=>['case','idea'].includes(x.type)).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.title)} · v${x.version}</option>`).join('')}</select><label class="form-label" for="baidu-link">百度网盘分享链接</label><input class="field" id="baidu-link" name="link" type="url" maxlength="1000" value="${esc(c.link||'')}" placeholder="https://pan.baidu.com/s/分享标识"><label class="form-label" for="baidu-code">提取码（可选）</label><input class="field" id="baidu-code" name="code" maxlength="4" pattern="[A-Za-z0-9]{4}" value="${esc(c.code||'')}" placeholder="4 位字母或数字"><label class="form-label" for="delivery-note">交付说明（可选）</label><textarea class="field" id="delivery-note" name="note" rows="4" maxlength="1000" placeholder="例如：包含 PDF、Python 代码与结果图表；解压密码为……">${esc(c.note||'')}</textarea><label class="check"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}><span>开启此商品的网盘交付演示</span></label><p class="error" id="delivery-error" role="alert"></p><button class="btn" type="submit">保存交付设置</button></form><p class="fineprint">只填写分享链接，不要填写百度账号密码。设置保存后，在本机完成该商品模拟购买，即可在“我的下载”中看到网盘交付。</p><div class="actions"><a class="text-link" href="#/product/${p.id}">查看商品并测试购买</a><a class="text-link" href="#/account/downloads">查看本机交付记录</a></div></div></section>`;}
  function adminCoupons(){const c=state.coupons.find(c=>c.code===state.editingCoupon)||{code:'',kind:'percent',value:20,minimum:0,start:'',end:'',active:true};return `<section class="container section"><div class="page-heading"><div class="eyebrow">STORE MANAGEMENT / DEMO</div><h1>优惠券管理</h1><p>自行设定券码、优惠规则与使用期限。</p></div>${adminNav('coupons')}<div class="notice">管理功能演示：配置仅保存于当前浏览器，不具备真实管理员权限，也不会同步给其他设备。正式营业时需要接入后台登录、数据库和服务端校验。</div><div class="admin-layout"><div class="panel"><div class="section-title"><h2>已设定的优惠券</h2><button class="btn secondary small" data-action="new-coupon">新增优惠券</button></div>${state.coupons.length?`<div class="table-wrap"><table><thead><tr><th>券码 / 规则</th><th>状态与期限</th><th>操作</th></tr></thead><tbody>${state.coupons.map(x=>`<tr><td><b>${esc(x.code)}</b><br>${x.kind==='percent'?'优惠 '+x.value+'%':'减 ¥'+money(x.value)} · ${x.minimum?'满 ¥'+money(x.minimum):'无门槛'}</td><td><span class="status ${x.active?'':'pending'}">${x.active?'已启用':'已停用'}</span><br><small>${esc(x.start||'即日起')} 至 ${esc(x.end||'不限期')}</small></td><td><div class="actions"><button class="text-link" data-action="edit-coupon" data-code="${esc(x.code)}">编辑</button><button class="text-link" data-action="toggle-coupon" data-code="${esc(x.code)}">${x.active?'停用':'启用'}</button></div></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">还没有优惠券，可在右侧添加。</p>'}<p class="fineprint">每笔订单限用一张券，不叠加。门槛按优惠前商品小计计算。日期按当前设备时区计算，截止日期包含当天。</p><a class="text-link" href="#/catalog">前往商城测试优惠</a></div><div class="panel"><h2>${state.editingCoupon?'编辑优惠券':'新增优惠券'}</h2><form id="coupon-admin-form"><label class="form-label" for="admin-code">优惠码</label><input class="field" id="admin-code" name="code" value="${esc(c.code)}" placeholder="例如 SUMMER20" minlength="3" maxlength="24" pattern="[A-Za-z0-9-]{3,24}" title="3 至 24 位英文字母、数字或短横线" required><label class="form-label" for="admin-kind">优惠方式</label><select class="field" id="admin-kind" name="kind"><option value="percent" ${c.kind==='percent'?'selected':''}>折扣：按比例减免</option><option value="fixed" ${c.kind==='fixed'?'selected':''}>满减：固定金额</option></select><label class="form-label" id="admin-value-label" for="admin-value">${c.kind==='percent'?'减免百分比（20 表示八折）':'减免金额（元）'}</label><input class="field" id="admin-value" name="value" type="number" min="${c.kind==='percent'?1:0.01}" max="${c.kind==='percent'?100:100000}" step="${c.kind==='percent'?1:0.01}" value="${c.kind==='fixed'?money(c.value):c.value}" required><label class="form-label" for="admin-minimum">最低消费金额（元，0 表示无门槛）</label><input class="field" id="admin-minimum" name="minimum" type="number" min="0" max="100000" step="0.01" value="${money(c.minimum)}" required><div class="date-fields"><div><label class="form-label" for="admin-start">开始日期（可选）</label><input class="field" id="admin-start" name="start" type="date" value="${esc(c.start)}"></div><div><label class="form-label" for="admin-end">截止日期（可选）</label><input class="field" id="admin-end" name="end" type="date" value="${esc(c.end)}"></div></div><label class="check"><input type="checkbox" name="active" ${c.active?'checked':''}><span>保存后启用</span></label><p class="error" id="admin-error" role="alert"></p><button class="btn wide" type="submit">保存优惠券</button></form></div></div></section>`;}
  window.addEventListener('storage',e=>{if(e.key!==storageKey)return;syncCoupons();if(getRoute().parts[0]==='checkout'&&$('#checkout-totals')){const ids=checkoutIds();$('#checkout-totals').innerHTML=totalsHTML(ids);$('#checkout-submit').textContent=`创建演示订单 · ¥${money(totals(ids).total)}`;toast('优惠券规则已更新，请确认结算金额。');}if(getRoute().parts[0]==='admin')render();});
  const articles={
    guide:['购买与体验说明','<h2>这是一家可交互的演示商店</h2><p>待梦归数模展示数学建模资料、辅导课程与解题思路的售卖体验。目前商品、售价、课程目录和会员权益均为示例，不构成实际销售承诺。</p><h2>如何完整体验</h2><ol><li>在商品列表浏览、搜索或按赛事筛选。</li><li>查看商品详情，试读思路资料或文字课程。</li><li>添加购物车，结算时可输入 DEMO20 获得演示 8 折优惠。</li><li>保留示例邮箱，勾选协议，创建演示订单。</li><li>模拟支付成功后，在个人中心下载示例笔记或打开文字课程。</li></ol><h2>数据保留方式</h2><p>购物车、收藏、体验昵称、订单和学习进度仅保存在当前浏览器。更换设备、清理浏览器或使用无痕模式后，数据可能无法保留。结算邮箱不会保存或用于发送通知。</p><h2>正式销售前</h2><p>需要补齐真实商品资料和授权、商户收款、用户登录、订单服务、支付回调、售后规则和安全交付。本站当前不进行真实支付、身份验证或防盗验证。</p>'],
    terms:['用户协议 · 演示版','<p>本协议说明演示站的体验边界。正式销售协议将在运营主体和真实商品确认后另行发布。</p><h2>服务性质</h2><p>本站仅提供页面展示和本地模拟流程。点击模拟支付不会产生扣款，页面显示的订单状态不是任何支付机构的交易凭证。</p><h2>内容使用</h2><p>示例内容用于学习和功能体验。请遵守内容版权与所参加赛事的规则，独立完成研究并规范标注引用，不将示例视作获奖保证。</p><h2>账户与数据</h2><p>前台无需登录。本站不保存密码，不验证手机号或邮箱。体验数据可在账户设置中主动清除。</p><h2>售后说明</h2><p>当前不涉及实际付款、履约或退款。正式营业时会在购买前明确交付内容、期限、更新和退款条件。</p>'],
    privacy:['隐私说明 · 演示版','<h2>此演示应用保存什么</h2><p>本站将购物车、收藏、体验昵称、演示订单和课程进度存储在当前设备的浏览器 localStorage 中，用于刷新后继续体验。这些数据不由本应用提交到订单服务器。</p><h2>输入和访问</h2><p>结算邮箱只用于表单格式校验，不保存、不发信；建议直接使用 demo@example.com。本站未接入第三方统计或广告脚本。网站托管平台可能按其政策处理 IP 地址等必要访问日志。</p><h2>删除与控制</h2><p>可在“个人中心 → 账户设置”清除本站保存的演示数据，也可以通过浏览器网站数据设置删除。更换浏览器或设备不会自动同步数据。</p><h2>正式版变化</h2><p>未来接入登录、收款和通知服务时，需要重新说明运营主体、处理目的、保存期限、服务提供方及联系渠道。</p>']
  };
  function article(key){const [title,body]=articles[key];return `<section class="container section"><article class="panel article"><div class="breadcrumbs"><a href="#/">首页</a> / ${title}</div><h1>${title}</h1>${body}</article></section>`;}
  function notFound(){return `<section class="container section">${empty('这页内容暂时不存在','可以回到商品列表，继续探索。')}</section>`;}
  function getRoute(){let raw=location.hash.slice(1)||'/';const [path,q]=raw.split('?');return {parts:path.split('/').filter(Boolean),params:new URLSearchParams(q||'')};}
  function render(){const {parts,params}=getRoute(),page=parts[0]||'home';let html='',title='数学建模研习商店';if(page==='home')html=home();else if(page==='catalog'){html=catalog(params);title='探索建模内容';}else if(page==='product'){html=detail(product(parts[1]));title=product(parts[1])?.title||'商品';}else if(page==='lookup'){html=lookup();title='订单取货';}else if(page==='cart'){html=cart();title='购物车';}else if(page==='checkout'){html=checkout();title='确认订单';}else if(page==='result'){html=result(parts[1]);title='演示订单';}else if(page==='account'){html=account(parts[1]);title='订单与学习空间';}else if(page==='learn'){html=learn(parts[1]);title='学习空间';}else if(page==='membership'){html=membership();title='研习会员';}else if(page==='admin'){html=parts[1]==='delivery'?adminDelivery():adminCoupons();title=parts[1]==='delivery'?'商品交付配置':'优惠券管理演示';}else if(articles[page]){html=article(page);title=articles[page][0];}else html=notFound();main.innerHTML=html;document.title=`${title} · 待梦归数模`;document.querySelectorAll('[data-nav]').forEach(a=>{let active=a.dataset.nav===page;if(page==='catalog')active=params.get('event')?a.dataset.nav==='event':a.dataset.nav===params.get('type');a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});updateBadge();}
  function addToCart(id){if(!product(id))return;if(state.cart.includes(id)){toast('这份内容已经在购物车中了');return;}state.cart.push(id);persist();toast('已加入购物车');document.querySelectorAll(`[data-action="add-cart"][data-id="${id}"]`).forEach(b=>b.textContent='已加入购物车');}
  function setCatalogParam(key,value){const {params}=getRoute();if(value&&value!=='all'&&value!=='default')params.set(key,value);else params.delete(key);go('/catalog'+(params.size?'?'+params.toString():''));}
  function download(id){const p=product(id),o=latestOrder(id);if(!p||!o){toast('请先完成模拟购买');return;}if(!Number.isFinite(o.expires)||o.expires<Date.now()){toast('演示下载期限已到，请重新生成');render();return;}const content=`# ${p.title}\n\n待梦归数模 · 示例笔记\n\n版本：${p.version}\n演示订单：${o.id}\n体验标识：本机演示用户\n\n> 本文件为实际可下载的功能示例，不是正式商品、完整论文或课程。\n> 此标识为文本说明，不是防篡改水印。\n\n## 研究思路\n\n${p.desc}\n\n## 内容大纲\n\n${p.outline.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\n## 练习\n\n1. 明确研究问题，列出变量、单位和约束。\n2. 说明假设与数据来源。\n3. 用小型样例验证模型。\n4. 检查结果并说明局限。\n\n资料仅用于学习和研究，请遵守赛事规则与引用规范。\n`;const blob=new Blob(['\uFEFF',content],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`待梦归数模-${p.title}-示例.md`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('示例文件已开始下载');}
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;
    if(action==='new-coupon'){state.editingCoupon=null;render();$('#admin-code').focus();}
    if(action==='edit-coupon'){state.editingCoupon=b.dataset.code;render();$('#admin-code').focus();}
    if(action==='toggle-coupon'){syncCoupons();const c=state.coupons.find(c=>c.code===b.dataset.code);if(c){c.active=!c.active;persist();render();toast(c.active?'优惠券已启用':'优惠券已停用');}}
    if(action==='close-modal')closeModal();
    if(action==='account')go('/lookup');
    if(action==='support')modal('联系待梦归数模','<p>客服渠道尚未配置。正式上线前，将在此添加你的客服微信、邮箱或在线咨询入口。</p><p>当前可以通过商品大纲和购买须知了解演示范围。</p><button class="btn secondary" data-action="close-modal">我知道了</button>');
    if(action==='add-cart'){if(state.cart.includes(id))go('/cart');else addToCart(id);}
    if(action==='buy'){if(product(id))go('/checkout?buy='+encodeURIComponent(id));}
    if(action==='remove-cart'){state.cart=state.cart.filter(x=>x!==id);persist();render();toast('已移除商品');}
    if(action==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();b.classList.toggle('favorite-on',state.favorites.includes(id));b.setAttribute('aria-pressed',state.favorites.includes(id));b.textContent=state.favorites.includes(id)?'已收藏':'收藏';toast(state.favorites.includes(id)?'已收藏，可在个人中心查看':'已取消收藏');}
    if(action==='home-filter'){state.homeType=b.dataset.type;const y=scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-action="home-filter"][data-type="${state.homeType}"]`).focus({preventScroll:true});}
    if(action==='catalog-filter')setCatalogParam('type',b.dataset.type);
    if(action==='detail-tab'){state.detailTab=b.dataset.tab;$('#detail-body').innerHTML=detailContent(product(id),state.detailTab);$('#detail-body').setAttribute('aria-labelledby',`tab-${state.detailTab}`);document.querySelectorAll('[data-action="detail-tab"]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',t===b);});}
    if(action==='preview'){const p=product(id);modal(`${p.title} · 文字试看`,`<div class="reading">${previewText(p)}</div><p class="fineprint">示例文字课程，尚未提供视频素材。</p>`);}
    if(action==='apply-coupon'){const code=$('#coupon-input').value.trim().toUpperCase(),subtotal=checkoutIds().reduce((sum,id)=>sum+product(id).price,0),result=validateCoupon(code,subtotal);state.coupon=result.error?null:code;$('#coupon-message').textContent=result.error||`已应用 ${code}，优惠 ¥${money(result.discount)}`;$('#coupon-message').style.color=result.error?'#b6553a':'var(--green)';$('#checkout-totals').innerHTML=totalsHTML(checkoutIds());$('#checkout-submit').textContent=`创建演示订单 · ¥${money(totals(checkoutIds()).total)}`;}
    if(action==='pay-fail'){$('#payment-error').innerHTML='<p>模拟支付未完成，订单仍为待支付。可以再次点击“模拟支付成功”重试，不会重复创建订单。</p>';toast('已模拟支付失败');}
    if(action==='pay-success'){const o=state.orders.find(o=>o.id===id);if(o&&o.status==='pending'){o.status='delivered';o.delivered=Date.now();o.expires=Date.now()+86400000;state.cart=state.cart.filter(x=>!o.items.includes(x));state.coupon=false;persist();render();toast('模拟支付成功，示例内容已交付');}}
    if(action==='save-receipt'){const o=state.orders.find(o=>o.id===id);if(!o)return;const body=`待梦归数模 · 演示购买凭证\n\n订单凭证：${o.id}\n创建时间：${date(o.created)}\n商品：${o.items.map(id=>product(id).title).join('、')}\n演示金额：¥${money(o.total)}\n状态：${o.status==='delivered'?'演示已交付':'待模拟支付'}\n\n请在本站“订单取货”中输入完整凭证。\n演示订单只存在于当前浏览器，清除数据后凭证也无法找回该演示订单。正式版需服务端订单存储才支持跨设备取货。\n凭证相当于领取密钥，请勿公开或转发。\n`;const url=URL.createObjectURL(new Blob(['\uFEFF',body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='待梦归数模-购买凭证.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('购买凭证文件已生成');}
    if(action==='download')download(id);
    if(action==='renew'){const o=latestOrder(id);if(o){o.expires=Date.now()+86400000;persist();render();toast('已更新本机演示期限为 24 小时');}}
    if(action==='progress'){const p=product(id);if(p&&hasProduct(id)){state.progress[id]=Math.min(p.outline.length,Math.max(Number(state.progress[id])||0,Number(b.dataset.chapter)));persist();render();toast('学习进度已保存');}}
    if(action==='copy'){try{await navigator.clipboard.writeText(b.dataset.copy);toast((b.dataset.copyLabel||'订单凭证')+'已复制');}catch{modal('复制内容',`<p>长按或选中下方内容即可复制。</p><input class="field" readonly value="${esc(b.dataset.copy)}" aria-label="订单号">`);}}
    if(action==='clear-data')modal('清除本机演示数据','<p>将删除本站的体验昵称、购物车、收藏、订单和学习进度。此操作仅影响当前浏览器。</p><div class="actions"><button class="btn" data-action="confirm-clear">确认清除</button><button class="btn secondary" data-action="close-modal">保留数据</button></div>');
    if(action==='confirm-clear'){Object.assign(state,{cart:[],favorites:[],orders:[],profile:'',progress:{},coupon:false});persist();closeModal();render();toast('本机演示数据已清除');}
  });
  document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();const name=new FormData(e.target).get('nickname').trim().slice(0,24);if(!name){toast('请输入体验昵称');return;}state.profile=name;persist();if($('#modal').open)closeModal();go('/account/orders');toast('体验昵称已保存');}
    if(e.target.id==='delivery-admin-form'){e.preventDefault();const d=new FormData(e.target),id=String(d.get('product')),link=String(d.get('link')).trim(),code=String(d.get('code')).trim(),note=String(d.get('note')).trim(),enabled=d.get('enabled')==='on';if((link&&!validBaidu(link))||(enabled&&!link)){$('#delivery-error').textContent='请填写 https://pan.baidu.com/s/ 开头的有效分享链接。';return;}if(code&&!/^[A-Za-z0-9]{4}$/.test(code)){$('#delivery-error').textContent='提取码应为 4 位字母或数字，或留空。';return;}syncCoupons();state.deliveries[id]={link,code,note,enabled};persist();toast('交付设置已保存');$('#delivery-error').textContent='';}
    if(e.target.id==='lookup-form'){e.preventDefault();const value=String(new FormData(e.target).get('credential')).trim().toUpperCase();const order=state.orders.find(o=>o.id===value);if(order)go('/result/'+order.id);else $('#lookup-error').textContent='没有找到此凭证。请核对完整内容，并使用创建订单时的浏览器；演示版不支持跨设备查询。';}
    if(e.target.id==='coupon-admin-form'){e.preventDefault();const d=new FormData(e.target),code=String(d.get('code')).trim().toUpperCase(),kind=d.get('kind'),raw=Number(d.get('value')),minimum=Math.round(Number(d.get('minimum'))*100),start=String(d.get('start')),end=String(d.get('end'));syncCoupons();let error='';if(!/^[A-Z0-9-]{3,24}$/.test(code))error='券码需为 3 至 24 位字母、数字或短横线。';else if(state.coupons.some(c=>c.code===code&&c.code!==state.editingCoupon))error='此券码已存在，请编辑原券或换一个券码。';else if(!Number.isFinite(raw)||raw<=0||raw>100000||(kind==='percent'&&(raw>100||!Number.isInteger(raw))))error='比例优惠请输入 1 至 100 的整数；固定减免需大于 0。';else if(!Number.isFinite(minimum)||minimum<0)error='最低消费不能为负数。';else if(start&&end&&start>end)error='开始日期不能晚于截止日期。';if(error){$('#admin-error').textContent=error;return;}const next={code,kind,value:kind==='fixed'?Math.round(raw*100):raw,minimum,start,end,active:d.get('active')==='on'},index=state.coupons.findIndex(c=>c.code===state.editingCoupon);if(index>=0)state.coupons[index]=next;else state.coupons.push(next);state.editingCoupon=null;persist();render();toast('优惠券已保存，可到结算页使用');}
    if(e.target.id==='checkout-form'){e.preventDefault();const ids=checkoutIds();if(!ids.length)return;$('#checkout-submit').disabled=true;syncCoupons();if(state.coupon){const check=validateCoupon(state.coupon,ids.reduce((sum,id)=>sum+product(id).price,0));if(check.error){state.coupon=null;$('#checkout-totals').innerHTML=totalsHTML(ids);$('#checkout-submit').textContent=`创建演示订单 · ¥${money(totals(ids).total)}`;$('#checkout-submit').disabled=false;toast(check.error+' 金额已更新，请确认后重新提交。');return;}}const currentTotals=totals(ids), payment=new FormData(e.target).get('payment');const existing=state.orders.find(o=>o.status==='pending'&&o.total===currentTotals.total&&o.payment===payment&&o.items.slice().sort().join(',')===ids.slice().sort().join(','));if(existing){go('/result/'+existing.id);return;}const now=Date.now(),bytes=new Uint8Array(16);crypto.getRandomValues(bytes);const id=`DEMO-${now.toString(36).toUpperCase()}-${Array.from(bytes).map(x=>x.toString(16).padStart(2,'0')).join('').toUpperCase()}`;const o={id,items:[...ids],...currentTotals,couponCode:state.coupon||null,payment:currentTotals.total===0?'零元演示（无需支付）':payment,status:'pending',created:now};state.orders.unshift(o);state.orders=state.orders.slice(0,100);persist();go(`/result/${id}`);}
  });
  document.addEventListener('input',e=>{if(e.target.id==='search'){const {params}=getRoute();const q=e.target.value;if(q)params.set('q',q);else params.delete('q');history.replaceState(null,'','#/catalog'+(params.size?'?'+params.toString():''));$('#product-results').innerHTML=results(params);$('#result-count').textContent=`共 ${filtered(params).length} 项内容 · 均为示例商品`;}});
  document.addEventListener('change',e=>{if(e.target.id==='delivery-product'){state.deliveryProduct=e.target.value;render();}if(e.target.id==='event-filter')setCatalogParam('event',e.target.value);if(e.target.id==='sort')setCatalogParam('sort',e.target.value);if(e.target.id==='admin-kind'){const percent=e.target.value==='percent';$('#admin-value-label').textContent=percent?'减免百分比（20 表示八折）':'减免金额（元）';$('#admin-value').min=percent?'1':'0.01';$('#admin-value').max=percent?'100':'100000';$('#admin-value').step=percent?'1':'0.01';}});
  document.addEventListener('keydown',e=>{const tab=e.target.closest('[role="tab"]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const all=[...document.querySelectorAll('[role="tab"]')],i=all.indexOf(tab);const next=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;all[next].focus();all[next].click();}});
  window.addEventListener('hashchange',()=>{state.detailTab='intro';if($('#modal').open)closeModal();render();window.scrollTo(0,0);main.focus({preventScroll:true});});
  $('#year').textContent=new Date().getFullYear();render();
})();
